'use strict';
async function albumAdminAPI(body){const store=await TemuStore.read();if(!store.config.token)throw Error('Hubungkan server terlebih dahulu pada Pengaturan.');const response=await fetch('/api/album/admin',{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Temu-Album':'1','Authorization':'Bearer '+store.config.token},body:body?JSON.stringify(body):undefined,cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.error||'Pengaturan album belum tersedia.');return result.config;}
function albumLocalDate(iso){if(!iso)return '2026-11-21T20:30';const date=new Date(iso);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function albumShare(config){const url=new URL('/album',location.origin);url.hash='k='+config.key;return url.href;}
async function showAlbumSettings(){if(!await admin())return;try{const config=await albumAdminAPI();modal('Album bersama',`<p>QR album mengajak tamu berbagi foto dan video. QR ini terpisah dari QR check-in.</p><form id="album-config"><label>Nama album<input id="album-title" maxlength="120" value="${esc(config?.title||'Reva & Cesar')}" required></label><label>Galeri dapat dilihat<select id="album-mode"><option value="live" ${config?.mode==='live'?'selected':''}>Selama acara / langsung</option><option value="after" ${config?.mode!=='live'?'selected':''}>Pada tanggal dan jam yang ditentukan</option></select></label><label id="album-date-label">Tanggal dan jam pembukaan (waktu perangkat)<input id="album-release" type="datetime-local" value="${albumLocalDate(config?.releaseAt)}"></label><label>Nuansa awal<select id="album-preset">${[['original','Asli'],['film','Film'],['warm','Hangat'],['mono','Monokrom']].map(([value,label])=>`<option value="${value}" ${value===(config?.filter||'film')?'selected':''}>${label}</option>`).join('')}</select></label><label>Unggahan tamu<select id="album-uploads"><option value="y" ${config?.uploadsOpen!==false?'selected':''}>Dibuka</option><option value="n" ${config?.uploadsOpen===false?'selected':''}>Ditutup</option></select></label><button class="primary wide">${config?'Simpan pengaturan album':'Aktifkan album & buat QR'}</button></form><p class="hint">File asli disimpan di volume server. Batas 100 MB per file dan 2 GB untuk seluruh album. File album perlu ikut disalin saat mencadangkan server.</p><div id="album-share"></div>`);const mode=$('#album-mode'),date=$('#album-date-label');const update=()=>{date.hidden=mode.value==='live';$('#album-release').required=mode.value==='after';};mode.onchange=update;update();if(config)renderAlbumShare(config);$('#album-config').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const config=await albumAdminAPI({title:$('#album-title').value.trim(),mode:mode.value,releaseAt:mode.value==='after'?new Date($('#album-release').value).toISOString():'',filter:$('#album-preset').value,uploadsOpen:$('#album-uploads').value==='y'});renderAlbumShare(config);toast('Album tersimpan. QR tetap sama setelah pengaturan diperbarui.');}catch(e){toast(e.message);}finally{button.disabled=false;}};}catch(e){toast(e.message);}}
function renderAlbumShare(config){const url=albumShare(config),q=qrcode(0,'M');q.addData(url);q.make();const svg=q.createSvgTag(5,20);$('#album-share').innerHTML=`<div class="qr-preview album-admin-qr"><h3>Bagikan cerita dari mejamu</h3>${svg}<p>#foREVArwithCESAR</p><p class="hint">Pindai QR ini untuk foto, video, dan album bersama.</p><div class="actions"><a class="album-open-link" target="_blank" rel="noopener" href="${esc(url)}">Buka album ↗</a><button id="copy-album-link" type="button">Salin tautan album</button><button id="print-album-qr" type="button">Cetak QR meja</button></div></div>`;$('#copy-album-link').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Tautan album disalin.');}catch{modal('Tautan album',`<label>Salin tautan ini<input readonly value="${esc(url)}"></label>`);}};$('#print-album-qr').onclick=()=>{$('#print-area').innerHTML=`<section class="album-qr-print"><span>FROM YOUR TABLE, WITH LOVE</span><h1>Our shared moments.</h1><h2>#foREVArwithCESAR</h2>${svg}<p>Jepret tawa, pelukan, dan cerita kecil hari ini.</p><strong>Pindai untuk berbagi foto & video</strong><p>Tanpa aplikasi · Langsung dari HP kamu</p><small>Made by Cesar with love</small></section>`;window.print();};}
document.querySelector('#album-settings').onclick=showAlbumSettings;
